const PERIOD_TABLE = {
  1: ['07:00', '07:50'],
  2: ['07:50', '08:40'],
  3: ['08:40', '09:30'],
  4: ['09:45', '10:35'],
  5: ['10:35', '11:25'],
  6: ['13:00', '13:50'],
  7: ['13:50', '14:40'],
  8: ['14:40', '15:30'],
  9: ['15:45', '16:35'],
  10: ['16:35', '17:25']
};

const SESSION_SPLIT = 5; // Tiết <= 5: Buổi sáng; Tiết > 5: Buổi chiều
const VERIFIED = true;   // Đã xác minh chuẩn mốc giờ UEL

return [{
  json: {
    ...$input.first().json,
    mime_type: $input.first().json.mime_type || 'image/jpeg', // <-- Thêm dòng này
    period_table: PERIOD_TABLE,
    session_split: SESSION_SPLIT,
    period_table_verified: VERIFIED
  }
}];

const p = $input.first().json;
const T = p.period_table, split = p.session_split;
const maxP = Math.max(...Object.keys(T).map(Number));
const errors = [];
const op = p.operation;
if (!['parse_image', 'confirm_import'].includes(op)) errors.push('operation phai la parse_image hoac confirm_import');
if (!p.user_id) errors.push('thieu user_id');

const THU = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];
const WORDS = { hai: 1, ba: 2, tu: 3, tư: 3, nam: 4, năm: 4, sau: 5, sáu: 5, bay: 6, bảy: 6 };
const normThu = (v) => {
  const s = String(v || '').trim().toLowerCase();
  if (/^(cn|chủ nhật|chu nhat|8)$/.test(s)) return 0;
  const num = s.match(/(\d)/);
  if (num && Number(num[1]) >= 2 && Number(num[1]) <= 7) return Number(num[1]) - 1;
  const w = s.replace(/^th[ứu]\s*/, '');
  return Object.prototype.hasOwnProperty.call(WORDS, w) ? WORDS[w] : -1;
};
const isYmd = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(new Date(s + 'T00:00:00Z').getTime());
const wd = (s) => new Date(s + 'T00:00:00Z').getUTCDay();

let image = null;
const items = [];
if (op === 'parse_image') {
  let b64 = String(p.image_base64 || '');
  const m = b64.match(/^data:(image\/[a-z+.-]+);base64,/i);
  const mime = String(p.mime_type || (m && m[1]) || '').toLowerCase();
  b64 = b64.replace(/^data:[^,]*,/, '').replace(/\s+/g, '');
  if (!b64) errors.push('thieu image_base64');
  if (!['image/png', 'image/jpeg', 'image/jpg', 'image/webp'].includes(mime)) errors.push('mime_type phai la image/png, image/jpeg hoac image/webp');
  if (b64.length > 14000000) errors.push('anh qua lon (toi da khoang 10MB)');
  image = { mime_type: mime === 'image/jpg' ? 'image/jpeg' : mime, data: b64 };
}
if (op === 'confirm_import') {
  if (!Array.isArray(p.selected_items) || p.selected_items.length === 0) errors.push('selected_items phai la mang khong rong');
  else if (p.selected_items.length > 40) errors.push('toi da 40 muc moi lan nhap');
  else p.selected_items.forEach((it, i) => {
    const tag = '[' + (i + 1) + '] ';
    const name = String(it.ten_mon || '').trim();
    const sp = Number.parseInt(it.start_period, 10), ep = Number.parseInt(it.end_period, 10);
    const t = normThu(it.thu);
    if (!name) errors.push(tag + 'thieu ten_mon');
    if (t < 0) errors.push(tag + 'thu khong hop le');
    if (!(sp >= 1 && ep >= sp && T[sp] && T[ep])) errors.push(tag + 'tiet khong hop le (1-' + maxP + ', start <= end)');
    else if ((sp <= split) !== (ep <= split)) errors.push(tag + 'tiet bat dau/ket thuc khac buoi');
    if (!isYmd(it.applied_date)) errors.push(tag + 'applied_date phai dang YYYY-MM-DD');
    if (!isYmd(it.recurrence_until)) errors.push(tag + 'recurrence_until phai dang YYYY-MM-DD');
    else if (isYmd(it.applied_date) && it.recurrence_until < it.applied_date) errors.push(tag + 'recurrence_until phai >= applied_date');
    if (isYmd(it.applied_date) && t >= 0 && wd(it.applied_date) !== t) errors.push(tag + 'applied_date khong trung ' + THU[t]);
    items.push({
      ten_mon: name, thu: t >= 0 ? THU[t] : null, start_period: sp, end_period: ep,
      applied_date: it.applied_date, recurrence_until: it.recurrence_until,
      phong_hoc: it.phong_hoc ? String(it.phong_hoc).trim() : null, giang_vien: it.giang_vien ? String(it.giang_vien).trim() : null
    });
  });
}
if (errors.length) return [{ json: { valid: false, response: { status: 'error', error_code: 'INVALID_INPUT', message: errors.join('; ') } } }];
return [{ json: {
  valid: true, operation: 'get_user', data: { external_user_id: String(p.user_id) },
  op, user_id: String(p.user_id), image, items, request_id: p.request_id ? Number.parseInt(p.request_id, 10) || null : null,
  period_table: T, session_split: split, period_table_verified: p.period_table_verified === true
} }];

const r = $input.first().json;
if (!r.success || !r.rows[0]) return [{ json: { ok: false, response: { status: 'error', error_code: 'USER_NOT_FOUND', message: 'Khong tim thay user_id.' } } }];
return [{ json: { ok: true, user: r.rows[0] } }];

const ctx = $('Validate Input').first().json;
const T = ctx.period_table;
const tableText = Object.keys(T).map((k) => 'Tiết ' + k + ': ' + T[k][0] + '-' + T[k][1]).join('; ');
const systemPrompt = [
  'Bạn là bộ trích xuất thời khóa biểu từ ảnh chụp/ảnh màn hình. CHỈ trả về MỘT đối tượng JSON hợp lệ, không markdown, không giải thích.',
  'Schema: {"items":[{"ten_mon":string,"thu":"Thứ Hai|Thứ Ba|Thứ Tư|Thứ Năm|Thứ Sáu|Thứ Bảy|Chủ Nhật","start_period":integer,"end_period":integer,"phong_hoc":string|null,"giang_vien":string|null,"ngay_bat_dau":"YYYY-MM-DD"|null,"ngay_ket_thuc":"YYYY-MM-DD"|null}]}',
  'Quy tắc:',
  '- Mỗi buổi học là một phần tử; môn học nhiều thứ trong tuần thì tách thành nhiều phần tử.',
  '- start_period/end_period là SỐ TIẾT (ví dụ "Tiết 1-4" => 1 và 4). Nếu ảnh ghi giờ thay vì tiết, chọn tiết khớp nhất theo bảng: ' + tableText + '.',
  '- Không thấy ngày bắt đầu/kết thúc học thì để null. Không bịa dữ liệu; không chắc chắn thì bỏ qua phần tử đó.'
].join('\n');
const body = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ inline_data: { mime_type: ctx.image.mime_type, data: ctx.image.data } }, { text: 'Trích xuất thời khóa biểu trong ảnh này.' }] }],
  generationConfig: { temperature: 0, responseMimeType: 'application/json' }
};
return [{ json: { gemini_body: body } }];

const ctx = $('Validate Input').first().json;
const T = ctx.period_table, split = ctx.session_split;
const res = $input.first().json;
const fail = (code, message) => [{ json: { found: false, response: { status: 'error', error_code: code, message } } }];
if (res.error) return fail('VISION_FAILED', 'Loi goi Gemini Vision: ' + (typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error))));

let data;
try {
  const text = (res?.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
  if (!text) return fail('VISION_FAILED', 'Gemini tra ve noi dung rong');
  data = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) { return fail('VISION_FAILED', 'Khong parse duoc JSON tu Gemini: ' + e.message); }

const THU = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];
const WORDS = { hai: 1, ba: 2, tu: 3, tư: 3, nam: 4, năm: 4, sau: 5, sáu: 5, bay: 6, bảy: 6 };
const normThu = (v) => {
  const s = String(v || '').trim().toLowerCase();
  if (/^(cn|chủ nhật|chu nhat|8)$/.test(s)) return 0;
  const num = s.match(/(\d)/);
  if (num && Number(num[1]) >= 2 && Number(num[1]) <= 7) return Number(num[1]) - 1;
  const w = s.replace(/^th[ứu]\s*/, '');
  return Object.prototype.hasOwnProperty.call(WORDS, w) ? WORDS[w] : -1;
};
const isYmd = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(new Date(s + 'T00:00:00Z').getTime());
const addDays = (ymd, n) => new Date(new Date(ymd + 'T00:00:00Z').getTime() + n * 86400000).toISOString().slice(0, 10);
const wdOf = (ymd) => new Date(ymd + 'T00:00:00Z').getUTCDay();
const nextOn = (fromYmd, wd) => addDays(fromYmd, (wd - wdOf(fromYmd) + 7) % 7);
const today = new Date(Date.now() + 7 * 3600000).toISOString().slice(0, 10);

const warnings = [];
if (!ctx.period_table_verified) warnings.push({ code: 'PERIOD_TABLE_UNVERIFIED', message: 'Bang quy doi tiet UEL dang dung gia tri mac dinh chua xac minh; hay kiem tra gio hoc truoc khi xac nhan.' });
let assumed = false;
const seen = new Set();
const items = [];
for (const raw of (Array.isArray(data.items) ? data.items : [])) {
  const name = String(raw.ten_mon || '').trim();
  const wd = normThu(raw.thu);
  const sp = Number.parseInt(raw.start_period, 10), ep = Number.parseInt(raw.end_period, 10);
  if (!name || wd < 0 || !(sp >= 1 && ep >= sp && T[sp] && T[ep]) || ((sp <= split) !== (ep <= split))) {
    warnings.push({ code: 'SKIPPED_ITEM', message: 'Bo qua muc khong hop le: ' + (name || '(khong ten)') });
    continue;
  }
  let applied = isYmd(raw.ngay_bat_dau) ? nextOn(raw.ngay_bat_dau, wd) : null;
  if (!applied) { applied = nextOn(today, wd); assumed = true; }
  let until = isYmd(raw.ngay_ket_thuc) && raw.ngay_ket_thuc >= applied ? raw.ngay_ket_thuc : null;
  if (!until) { until = addDays(applied, 15 * 7); assumed = true; }
  const key = [name.toLowerCase(), wd, sp, ep, applied].join('|');
  if (seen.has(key)) continue;
  seen.add(key);
  const range = T[sp][0] + '-' + T[ep][1];
  items.push({
    ten_mon: name, thu: THU[wd], start_period: sp, end_period: ep, applied_date: applied, recurrence_until: until,
    phong_hoc: raw.phong_hoc ? String(raw.phong_hoc).trim() : null, giang_vien: raw.giang_vien ? String(raw.giang_vien).trim() : null,
    time_range: range, ca_hoc_hoac_gio: 'Tiết ' + sp + '-' + ep + ' (' + range + ')'
  });
}
if (assumed) warnings.push({ code: 'DEFAULT_DATES_ASSUMED', message: 'Anh khong co du ngay hoc: applied_date = buoi gan nhat, recurrence_until = +15 tuan. Hay chinh lai truoc khi xac nhan.' });
if (items.length === 0) return fail('NO_SCHEDULE_FOUND', 'Khong nhan dien duoc mon hoc nao trong anh.');
return [{ json: { found: true, items, warnings } }];

const u = $('Check User').first().json.user;
const p = $input.first().json;
return [{ json: { operation: 'insert_request', data: {
  user_id: u.user_id, user_command: '[anh] Nhap thoi khoa bieu', intent: 'import_schedule',
  parsed_json: { status: 'ok', source: 'image', items: p.items }, status: 'import_ready'
} } }];

const ctx = $('Validate Input').first().json;
const parsed = $('Parse Vision Output').first().json;
const r = $input.first().json;
const warnings = [...parsed.warnings];
let requestId = null;
if (r.success && r.rows[0]) requestId = r.rows[0].request_id;
else warnings.push({ code: 'REQUEST_NOT_SAVED', message: 'Khong luu duoc yeu cau import: ' + (r.error || '') });
return [{ json: { response: {
  status: 'import_ready', request_id: requestId, items: parsed.items, warnings,
  period_table: ctx.period_table, period_table_verified: ctx.period_table_verified
} } }];

const ctx = $('Validate Input').first().json;
const T = ctx.period_table;
const u = $('Check User').first().json.user;
const fnv = (s, seed) => { let h = seed >>> 0; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h.toString(16).padStart(8, '0'); };

return ctx.items.map((it, idx) => {
  const key = [u.user_id, it.ten_mon.toLowerCase(), it.thu, it.start_period, it.end_period, it.applied_date].join('|');
  const eventId = 'aisecsch' + fnv(key, 2166136261) + fnv(key, 3074457345); // id co dinh (a-v, 0-9) => gui lai se tra 409, khong tao trung
  const st = T[it.start_period][0], en = T[it.end_period][1];
  const body = {
    id: eventId,
    summary: it.ten_mon,
    location: it.phong_hoc || undefined,
    description: ['Thời khóa biểu UEL', 'Tiết ' + it.start_period + '-' + it.end_period + ' (' + st + '-' + en + ')', it.giang_vien ? 'Giảng viên: ' + it.giang_vien : null].filter(Boolean).join('\n'),
    start: { dateTime: it.applied_date + 'T' + st + ':00+07:00', timeZone: 'Asia/Ho_Chi_Minh' },
    end: { dateTime: it.applied_date + 'T' + en + ':00+07:00', timeZone: 'Asia/Ho_Chi_Minh' },
    recurrence: ['RRULE:FREQ=WEEKLY;UNTIL=' + it.recurrence_until.replace(/-/g, '') + 'T165959Z'], // 23:59:59 gio VN cua ngay cuoi
    reminders: { useDefault: false, overrides: [{ method: 'popup', minutes: 30 }] }
  };
  return { json: { idx, item: it, event_id: eventId, start_hhmm: st, end_hhmm: en, gcal_body: body } };
});

const ctx = $('Validate Input').first().json;
const u = $('Check User').first().json.user;
const prepared = $('Build GCal Items').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);

const rem = (p) => new Date(new Date(p.item.applied_date + 'T' + p.start_hhmm + ':00+07:00').getTime() - 30 * 60000 + 7 * 3600000).toISOString().slice(0, 19).replace('T', ' ');
const ok = [], failed = [];
prepared.forEach((p, i) => {
  const r = results[i] || {};
  const code = r.statusCode;
  if (code === 200 || code === 201 || code === 409) {
    ok.push({
      ten_mon: p.item.ten_mon, thu: p.item.thu, start_period: p.item.start_period, end_period: p.item.end_period,
      applied_date: p.item.applied_date, recurrence_until: p.item.recurrence_until,
      ca_hoc_hoac_gio: 'Tiết ' + p.item.start_period + '-' + p.item.end_period + ' (' + p.start_hhmm + '-' + p.end_hhmm + ')',
      phong_hoc: p.item.phong_hoc, giang_vien: p.item.giang_vien,
      google_event_id: (code !== 409 && r.body && r.body.id) || p.event_id,
      already_existed: code === 409,
      remind_at: rem(p), reminder_text: 'Sap vao hoc: ' + p.item.ten_mon + ' luc ' + p.start_hhmm
    });
  } else {
    const detail = code ? 'HTTP ' + code : (typeof r.error === 'string' ? r.error : (r.error && r.error.message) || 'khong ro');
    failed.push({ ten_mon: p.item.ten_mon, thu: p.item.thu, reason: detail });
  }
});
return [{ json: { operation: 'import_schedules', data: { user_id: u.user_id, request_id: ctx.request_id, items: ok }, failed } }];

const agg = $('Interpret And Aggregate').first().json;
const r = $input.first().json;
const created = agg.data.items.map((x) => ({ ten_mon: x.ten_mon, thu: x.thu, google_event_id: x.google_event_id, already_existed: x.already_existed }));
if (agg.data.items.length === 0) {
  return [{ json: { response: { status: 'error', error_code: 'GCAL_IMPORT_FAILED', message: 'Khong tao duoc su kien nao tren Google Calendar.', failed: agg.failed } } }];
}
if (!r.success) {
  return [{ json: { response: { status: 'error', error_code: 'DB_ERROR', message: 'Da tao lich tren Google Calendar nhung chua luu duoc CSDL: ' + (r.error || '') + '. Gui lai se khong tao trung.', google_events: created, failed: agg.failed } } }];
}
if (agg.failed.length > 0) {
  return [{ json: { response: { status: 'error', error_code: 'PARTIAL_IMPORT', message: 'Mot so muc chua nhap duoc. Gui lai cac muc loi (se khong tao trung).', imported: r.rows, google_events: created, failed: agg.failed } } }];
}
return [{ json: { response: { status: 'import_done', imported_count: r.rows_count, imported: r.rows, google_events: created, failed: [] } } }];

